import React from "react";
import {
FaCode,
FaAward,
FaRocket,
FaUsers,
FaComments,
FaLightbulb,
FaCogs,
FaUsersCog,
FaClock,
FaBrain
} from "react-icons/fa";

const Skills = () => {
return (
<section className="skills-page">

  <div className="glow"></div>
  <div className="grid"></div>
  <div className="floating-orb"></div>

  <div className="header">
    <h1>Skills & Expertise</h1>
    <p>Engineering capabilities, certifications & real-world development experience</p>
  </div>

  <div className="bento">

    {/* TECH SKILLS */}
    <div className="card medium">
      <h2><FaCode /> Technical Skills</h2>
      <div className="tags">
        <span>Java</span>
        <span>React.js</span>
        <span>Spring Boot</span>
        <span>MySQL</span>
        <span>HTML</span>
        <span>CSS</span>
        <span>JavaScript</span>
        <span>Power BI</span>
      </div>
    </div>

    {/* CERTIFICATIONS */}
    <div className="card medium">
      <h2><FaAward /> Certifications</h2>
      <div className="list">
        <p>✔ Java Programming – NPTEL</p>
        <p>✔ Data Science for Engineers – NPTEL</p>
        <p>✔ SQL – HackerRank</p>
        <p>✔ Python – SoloLearn</p>
      </div>
    </div>

    {/* PREMIUM SMALL CARD */}
    <div className="card highlight">
      <h2><FaRocket /> What I Bring</h2>
      <p>Strong foundation in full-stack development with the ability to transform ideas into scalable applications.</p>
      <p>Focused on writing clean, efficient code and delivering real-world impact through technology.</p>
    </div>

  </div>

  {/* TIMELINE */}
  <div className="timeline-section">
    <h2>Internship Experience</h2>

    <div className="timeline">

      <div className="item">
        <div className="dot"></div>
        <div className="content">
          <h3>Full Stack Java Intern</h3>
          <h4>Retech Solutions</h4>
          <p>
            Designed and developed a Student Portal Management System using Spring Boot and REST APIs.
            Implemented secure authentication, optimized backend workflows, and integrated MySQL database
            for efficient data handling.
          </p>
          <p>
            Improved system performance by structuring modular backend logic and ensuring smooth API communication
            between frontend and backend.
          </p>
        </div>
      </div>

      <div className="item">
        <div className="dot"></div>
        <div className="content">
          <h3>Data Analytics Intern</h3>
          <h4>Retech Solutions</h4>
          <p>
            Built interactive Power BI dashboards by transforming raw datasets into actionable insights.
            Performed data cleaning, preprocessing, and visualization to support data-driven decision making.
          </p>
          <p>
            Enhanced reporting efficiency by identifying key performance metrics and presenting them through
            clear, visually structured dashboards.
          </p>
        </div>
      </div>

    </div>
  </div>

  {/* SOFT SKILLS */}
  <div className="soft-card">
    <h2>Soft Skills</h2>

    <div className="chips">
      <span><FaUsers /> Teamwork</span>
      <span><FaComments /> Communication</span>
      <span><FaLightbulb /> Problem Solving</span>
      <span><FaCogs /> Adaptability</span>
      <span><FaBrain /> Creativity</span>
      <span><FaUsersCog /> Leadership</span>
      <span><FaClock /> Time Management</span>
    </div>
  </div>

  <style>{`

    .skills-page{
      min-height:100vh;
      padding:40px 10%;
      font-family:"Poppins",sans-serif;
      background: radial-gradient(circle at top,#0b1220,#050816);
      color:white;
      position:relative;
      overflow:hidden;
    }

    .glow{
      position:absolute;
      width:500px;
      height:500px;
      background:radial-gradient(circle,#38BDF8,transparent 70%);
      top:-180px;
      right:-120px;
      filter:blur(80px);
      opacity:0.25;
    }

    .grid{
      position:absolute;
      inset:0;
      background-image:
        linear-gradient(rgba(56,189,248,0.05) 1px, transparent 1px),
        linear-gradient(90deg, rgba(56,189,248,0.05) 1px, transparent 1px);
      background-size:60px 60px;
      opacity:0.2;
    }

    .floating-orb{
      position:absolute;
      width:200px;
      height:200px;
      border-radius:50%;
      background:#38BDF8;
      filter:blur(120px);
      bottom:10%;
      left:5%;
      opacity:0.15;
      animation: float 6s infinite alternate;
    }

    @keyframes float{
      0%{ transform:translateY(0); }
      100%{ transform:translateY(-30px); }
    }

    .header{
      text-align:center;
      margin-bottom:40px;
    }

    .header h1{
      font-size:44px;
      color:#38BDF8;
    }

    .header p{
      color:#94a3b8;
      margin-top:8px;
    }

    .bento{
      display:grid;
      grid-template-columns:1.5fr 1.5fr 1fr;
      gap:20px;
      margin-bottom:50px;
    }

    .card{
      background:rgba(255,255,255,0.04);
      border:1px solid rgba(56,189,248,0.2);
      border-radius:16px;
      padding:18px;
      backdrop-filter:blur(12px);
      transition:0.3s;
    }

    .card:hover{
      transform:translateY(-6px);
      border-color:#38BDF8;
      box-shadow:0 0 25px rgba(56,189,248,0.25);
    }

    .medium{ min-height:160px; }

    .highlight{
      background:linear-gradient(135deg, rgba(56,189,248,0.15), rgba(56,189,248,0.05));
      display:flex;
      flex-direction:column;
      justify-content:center;
    }

    h2{
      color:#38BDF8;
      margin-bottom:12px;
      display:flex;
      gap:8px;
      align-items:center;
    }

    .tags{
      display:flex;
      flex-wrap:wrap;
      gap:10px;
    }

    .tags span{
      padding:6px 12px;
      border-radius:20px;
      background:rgba(56,189,248,0.1);
      border:1px solid rgba(56,189,248,0.3);
      font-size:13px;
      color:#cbd5e1;
    }

    .list p{
      color:#cbd5e1;
      margin:6px 0;
    }

    .timeline-section h2{
      color:#38BDF8;
      margin-bottom:20px;
    }

    .timeline{
      position:relative;
      margin-left:10px;
    }

    .timeline::before{
      content:"";
      position:absolute;
      left:8px;
      top:0;
      bottom:0;
      width:2px;
      background:#38BDF8;
      opacity:0.4;
    }

    .item{
      display:flex;
      gap:15px;
      margin-bottom:30px;
    }

    .dot{
      width:14px;
      height:14px;
      border-radius:50%;
      background:#38BDF8;
      box-shadow:0 0 12px #38BDF8;
      margin-top:6px;
    }

    .content h3{ color:#e2e8f0; }
    .content h4{ color:#38BDF8; font-size:13px; }
    .content p{ color:#cbd5e1; line-height:1.6; }

    .soft-card{
      margin-top:50px;
      padding:25px;
      border-radius:16px;
      background:rgba(255,255,255,0.04);
      border:1px solid rgba(56,189,248,0.2);
      text-align:center;
    }

    .chips{
      display:flex;
      flex-wrap:wrap;
      justify-content:center;
      gap:12px;
    }

    .chips span{
      padding:8px 14px;
      border-radius:20px;
      background:rgba(56,189,248,0.1);
      border:1px solid rgba(56,189,248,0.3);
      display:flex;
      gap:6px;
      align-items:center;
      color:#cbd5e1;
    }

    @media(max-width:900px){
      .bento{
        grid-template-columns:1fr;
      }
    }

  `}</style>

</section>
  );
};

export default Skills;
